                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = []
            exterior = False
            while q:
                x, y = q.popleft()
                region.append((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    exterior = True
                for a, b in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
